from collections import Counter

df = pd.read_excel('/tmp/extracted/food_duplicates.xls', engine='xlrd')

# Get all column headers
headers = df.columns.tolist()
print("Column headers:", headers)

# Get all cell values (excluding headers)
all_values = []
for col in df.columns:
    for item in df[col]:
        all_values.append(item.lower())

# Count all items (headers + values)
all_items = headers + all_values
item_counts = Counter(all_items)

# Find items that appear only once
unique_items = {item: count for item, count in item_counts.items() if count == 1}

