{"code": "import pandas as pd
from collections import defaultdict

df = pd.read_excel('/tmp/extracted/food_duplicates.xls', engine='xlrd')

# Build a mapping from food name to columns it appears in
food_to_columns = defaultdict(list)
for col in df.columns:
    for item in df[col]:
        food_to_columns[item.lower()].append(col)

# Find foods that appear in multiple columns
multi_column_foods = {food: cols for food, cols in food_to_columns.items() if len(cols) > 1}

print("Foods appearing in multiple columns:")
for food, cols in sorted(multi_column_foods.items()):
    print(f"  '{food}' -> {cols}")

print(f"\nTotal foods appearing in multiple columns: {len(multi_column_foods)}")

# Find foods that appear only in one column
single_column_foods = {food: cols for food, cols in food_to_columns.items() if len(cols) == 1}
print(f"\nTotal foods appearing in only one column: {len(single_column_foods)}")"}

